  "finding_class": "metadata-only",
  "rationale": "Both answers are valid, but the national split is materially overstated. Indonesian uses permanen for the sense, while Malaysian Malay uses kekal; however, Malaysian PRPM also accepts permanen as a synonym for kekal/tetap, and tetap is an accepted equivalent in both varieties. The relation should be reframed as a preference contrast, and the absent contrast field should explicitly state that this is not a false-friend distinction.",
  "claim_reviews": [
    {
      "subject": "English cue and sense",
      "conclusion": "Accurate. Permanent means lasting for a long time or forever, consistent with lasting indefinitely.",
      "material_risk": false,
      "evidence_refs": [
        "https://dictionary.cambridge.org/dictionary/english/permanent"
      ]
    },
    {
      "subject": "Indonesian answer: permanen",
      "conclusion": "Valid and ordinary for the intended Indonesian sense; KBBI defines permanen as tetap, not temporary, and lasting without meaningful change.",
      "material_risk": false,
      "evidence_refs": [
        "https://kbbi.web.id/permanen"
      ]
    },
    {
      "subject": "Malaysian answer: kekal",
      "conclusion": "Valid and well-supported for Malaysian Malay; PRPM defines kekal as continuing, not disappearing or changing, and synonymous with tetap.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=72508&keyword=Kekal"
      ]
    },
    {
      "subject": "Cross-variety overlap and national split",
      "conclusion": "Material overlap exists. Malaysian PRPM records permanen as an accepted form meaning kekal or tetap, while tetap itself covers permanent or non-temporary meanings in both varieties. The pair therefore teaches a usage preference, not a clean national-exclusive contrast. Dictionary evidence confirms acceptance but does not establish comparative frequency.",
      "material_risk": true,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=115704&keyword=permanen",
        "https://prpm.dbp.gov.my/Cari1?d=73980&keyword=kekal+nya",
        "https://kbbi.web.id/tetap"
      ]
    },
    {
      "subject": "Final relation",
      "conclusion": "Different-common-word is too categorical for the current card. It should be revised to a preference-oriented relation or accompanied by an explicit note that permanen is also accepted in Malaysian Malay and tetap is shared.",
      "material_risk": true,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=115704&keyword=permanen",
        "https://prpm.dbp.gov.my/Cari1?d=73980&keyword=kekal+nya",
        "https://kbbi.web.id/tetap"
      ]
    },
    {
      "subject": "False-friend contrast",
      "conclusion": "No false friend is present. Permanen and permanent are transparently related, and the Indonesian and Malaysian forms overlap semantically. The blank contrast field should explicitly say that this is a shared-equivalent/preference contrast rather than a false-friend contrast.",
      "material_risk": true,
      "evidence_refs": [
        "https://dictionary.cambridge.org/dictionary/english/permanent",
        "https://prpm.dbp.gov.my/Cari1?d=115704&keyword=permanen",
        "https://kbbi.web.id/permanen"
      ]
    }
  ]
}
